"""Generate .planning/M0-issues.json for GovTok (M0: Cal Hacks submission). v2, after the adversarial review."""
import json, sys

OUT = sys.argv[1]

SCHEMA_RULE = "Don't change `convex/schema.ts` (US5 owns it). If a field or index is missing, stop and ask."


def story(tid, title, sentence, desc, ac, area, size, spec, blocked, *, manual=(), files=None,
          priority="demo-critical", agent=True, schema_rule=True):
    parts = [sentence, ""] + list(desc)
    if files:
        parts += ["", f"Files this card owns: {files}. Put new code in these files so parallel cards don't collide."]
    if schema_rule:
        parts += ["", SCHEMA_RULE]
    parts += ["", "Acceptance criteria (agent-verifiable):"] + [f"- [ ] {a}" for a in ac]
    if manual:
        parts += ["", "Manual test (human, on a phone after merge to prod; not part of the agent review):"] + [f"- [ ] {m}" for m in manual]
    parts += ["", f"Priority: {priority}."]
    if not agent:
        parts += ["Not agent-doable: a human does this. `dispatch-cards` should skip it."]
    return {"tempId": tid, "title": f"{tid}: {title}", "body": "\n".join(parts), "area": area, "size": size,
            "specSection": spec, "blockedBy": list(blocked), "priority": priority, "agentDoable": agent}


def feature(tid, title, body, area, spec, stories):
    ids = [s["tempId"] for s in stories]
    return {"tempId": tid, "title": f"{tid}: {title}", "body": body + f"\n\nChildren: {', '.join(ids)}.",
            "label": "feature", "area": area, "specSection": spec, "stories": stories}


