FEATURES = [F1, F2, F3, F4, F5, F6, F7, F8]
stories = {s["tempId"]: s for f in FEATURES for s in f["stories"]}
ids = list(stories)
assert ids == [f"US{i}" for i in range(1, len(ids) + 1)], ids
for k, s in stories.items():
    for d in s["blockedBy"]:
        assert d in stories, (k, d)
        assert int(d[2:]) < int(k[2:]), f"{k} blocked by later {d}"

# longest dependency chain (by card count), computed from the edges
memo = {}
def chain(k):
    if k not in memo:
        best = []
        for d in stories[k]["blockedBy"]:
            c = chain(d)
            if len(c) > len(best):
                best = c
        memo[k] = best + [k]
    return memo[k]
critical = max((chain(k) for k in ids), key=len)

WAVES = [
    ["US1"],
    ["US4", "US5", "US6"],
    ["US7", "US11", "US12", "US15", "US16", "US20", "US21", "US26"],
    ["US8", "US13", "US17", "US19", "US22"],
    ["US10", "US14", "US23"],
    ["US9", "US18", "US24", "US25"],
    ["US27"],
]
HUMAN = ["US2", "US3", "US28"]
# validate waves: cap 3, every agent card exactly once, deps satisfied by earlier waves (human cards count as done from the start)
done = set(HUMAN)
seen = []
for i, w in enumerate(WAVES):
    for c in w:
        missing = [d for d in stories[c]["blockedBy"] if d not in done and d not in ("US28",)]
        assert not missing, f"wave {i}: {c} needs {missing}"
    done |= set(w)
    seen += w
assert sorted(seen + HUMAN, key=lambda x: int(x[2:])) == ids, set(ids) ^ set(seen + HUMAN)

